  "imp.rule1": ["1. Herkes sırayla gizli futbolcuyu görür. Biri sahtekârdır, futbolcuyu bilmez.", "1. Everyone sees the secret player in turn. One is the impostor and doesn't know it.", "1. Todos ven al jugador secreto por turnos. Uno es el impostor y no lo sabe.", "1. Todos veem o jogador secreto em turnos. Um é o impostor e não sabe quem é.", "1. Alle sehen nacheinander den geheimen Spieler. Einer ist der Hochstapler und kennt ihn nicht.", "1. Chacun voit le joueur secret à son tour. L'un est l'imposteur et ne le connaît pas.", "1. A turno tutti vedono il giocatore segreto. Uno è l'impostore e non lo conosce.", "1. يرى الجميع اللاعب السري بالتناوب. أحدكم محتال لا يعرفه."],
  "imp.rule2": ["2. 3 tur boyunca herkes futbolcuyla ilgili tek kelimelik ipucu söyler.", "2. For 3 rounds, everyone gives a one-word clue about the player.", "2. Durante 3 rondas, cada uno da una pista de una palabra sobre el jugador.", "2. Por 3 rodadas, cada um dá uma dica de uma palavra sobre o jogador.", "2. 3 Runden lang gibt jeder einen Ein-Wort-Hinweis zum Spieler.", "2. Pendant 3 manches, chacun donne un indice d'un mot sur le joueur.", "2. Per 3 turni, ognuno dà un indizio di una parola sul giocatore.", "2. لمدة 3 جولات، يعطي كل شخص تلميحًا من كلمة واحدة عن اللاعب."],
  "imp.rule3": ["3. Gizli oylamayla sahtekârı bulun. Yakalanan sahtekâr, futbolcuyu tahmin ederse yine kurtulur!", "3. Find the impostor in a secret vote. If caught, the impostor can still win by guessing the player!", "3. Encuentren al impostor en una votación secreta. ¡Si lo atrapan, aún puede ganar adivinando al jugador!", "3. Descubram o impostor numa votação secreta. Se for pego, ainda pode vencer adivinhando o jogador!", "3. Findet den Hochstapler per geheimer Abstimmung. Erwischt, kann er noch gewinnen, wenn er den Spieler errät!", "3. Trouvez l'imposteur par un vote secret. Démasqué, il peut encore gagner en devinant le joueur !", "3. Trovate l'impostore con un voto segreto. Se scoperto, può ancora vincere indovinando il giocatore!", "3. اكتشفوا المحتال بتصويت سري. إن كُشف، يمكنه الفوز بتخمين اللاعب!"],
  "imp.said": ["SÖYLEDİ", "DONE", "LISTO", "FEITO", "FERTIG", "FAIT", "FATTO", "تم"],
  "imp.saved": ["SAHTEKÂR KURTULDU!", "THE IMPOSTOR SURVIVED!", "¡EL IMPOSTOR SE SALVÓ!", "O IMPOSTOR SE SALVOU!", "DER HOCHSTAPLER HAT ÜBERLEBT!", "L'IMPOSTEUR S'EN SORT !", "L'IMPOSTORE SI È SALVATO!", "نجا المحتال!"],
  "imp.scores": ["SKOR TABLOSU", "SCOREBOARD", "MARCADOR", "PLACAR", "PUNKTESTAND", "CLASSEMENT", "CLASSIFICA", "لوحة النتائج"],
  "imp.seating": ["Telefon elden ele dolaşacak. İsimleri oturma sırasına göre yaz.", "The phone will be passed around. Enter names in seating order.", "El teléfono pasará de mano en mano. Escribe los nombres en orden.", "O celular vai passar de mão em mão. Escreva os nomes na ordem em que estão sentados.", "Das Handy wird weitergereicht. Namen in Sitzreihenfolge eingeben.", "Le téléphone va circuler. Écris les noms dans l'ordre des places.", "Il telefono passerà di mano in mano. Scrivi i nomi in ordine di posto.", "سيتم تمرير الهاتف بينكم. اكتبوا الأسماء بترتيب الجلوس."],
  "imp.secret": ["GİZLİ FUTBOLCU", "SECRET PLAYER", "JUGADOR SECRETO", "JOGADOR SECRETO", "GEHEIMER SPIELER", "JOUEUR SECRET", "GIOCATORE SEGRETO", "اللاعب السري"],
  "imp.seen_clues": ["GÖRDÜM · İPUÇLARINA GEÇ", "GOT IT · START CLUES", "VISTO · A LAS PISTAS", "VI · IR PARA AS DICAS", "GESEHEN · ZU DEN HINWEISEN", "VU · PASSER AUX INDICES", "VISTO · VAI AGLI INDIZI", "رأيت · إلى التلميحات"],
  "imp.seen_next": ["GÖRDÜM · SIRADAKİ: {name}", "GOT IT · NEXT: {name}", "VISTO · SIGUIENTE: {name}", "VI · PRÓXIMO: {name}", "GESEHEN · NÄCHSTER: {name}", "VU · SUIVANT : {name}", "VISTO · PROSSIMO: {name}", "رأيت · التالي: {name}"],
  "imp.show_card": ["KARTIMI GÖSTER", "SHOW MY CARD", "MOSTRAR MI CARTA", "MOSTRAR MINHA CARTA", "MEINE KARTE ZEIGEN", "VOIR MA CARTE", "MOSTRA LA MIA CARTA", "اعرض بطاقتي"],
  "imp.start": ["BAŞLA · {n} OYUNCU", "START · {n} PLAYERS", "EMPEZAR · {n} JUGADORES", "COMEÇAR · {n} JOGADORES", "START · {n} SPIELER", "COMMENCER · {n} JOUEURS", "INIZIA · {n} GIOCATORI", "ابدأ · {n} لاعبين"],
  "imp.tie": ["Oylar eşit çıktı, kimse suçlanmadı. Sahtekâr: {name}", "It's a tie, nobody was accused. Impostor: {name}", "Empate en la votación, nadie fue acusado. Impostor: {name}", "Empate na votação, ninguém foi acusado. Impostor: {name}", "Gleichstand, niemand wurde beschuldigt. Hochstapler: {name}", "Égalité, personne n'est accusé. Imposteur : {name}", "Parità, nessuno è stato accusato. Impostore: {name}", "تعادلت الأصوات ولم يُتهم أحد. المحتال: {name}"],
  "imp.title": ["Sahtekâr · {diff}", "Impostor · {diff}", "Impostor · {diff}", "Impostor · {diff}", "Hochstapler · {diff}", "Imposteur · {diff}", "Impostore · {diff}", "المحتال · {diff}"],
