  "imp.voting": ["GİZLİ OYLAMA", "SECRET VOTE", "VOTACIÓN SECRETA", "VOTAÇÃO SECRETA", "GEHEIME ABSTIMMUNG", "VOTE SECRET", "VOTO SEGRETO", "تصويت سري"],
  "imp.was_impostor": ["{name} SAHTEKÂRDI!", "{name} WAS THE IMPOSTOR!", "¡{name} ERA EL IMPOSTOR!", "{name} ERA O IMPOSTOR!", "{name} WAR DER HOCHSTAPLER!", "{name} ÉTAIT L'IMPOSTEUR !", "{name} ERA L'IMPOSTORE!", "{name} كان المحتال!"],
  "imp.who": ["Sence sahtekâr kim? Kimse görmesin.", "Who's the impostor? Keep it secret.", "¿Quién es el impostor? Que nadie lo vea.", "Quem é o impostor? Ninguém pode ver.", "Wer ist der Hochstapler? Geheim halten!", "Qui est l'imposteur ? Garde-le secret.", "Chi è l'impostore? Tienilo segreto.", "من المحتال برأيك؟ لا تدع أحدًا يرى."],
  "imp.you_are": ["SAHTEKÂRSIN", "YOU'RE THE IMPOSTOR", "ERES EL IMPOSTOR", "VOCÊ É O IMPOSTOR", "DU BIST DER HOCHSTAPLER", "TU ES L'IMPOSTEUR", "SEI L'IMPOSTORE", "أنت المحتال"],
  "imp.you_are_desc": ["Futbolcuyu bilmiyorsun. Diğerlerini dinle, belli etme!", "You don't know the player. Listen to the others and don't give yourself away!", "No conoces al jugador. ¡Escucha a los demás y no te delates!", "Você não conhece o jogador. Ouça os outros e não se entregue!", "Du kennst den Spieler nicht. Hör den anderen zu und verrate dich nicht!", "Tu ne connais pas le joueur. Écoute les autres et ne te trahis pas !", "Non conosci il giocatore. Ascolta gli altri e non tradirti!", "أنت لا تعرف اللاعب. استمع للآخرين ولا تكشف نفسك!"],
  "mode.chain.desc": ["Son futbolcuyla aynı kulüpte oynamış başka bir futbolcu yaz, zinciri uzat. Yanlış cevap bir can götürür; canı biten kaybeder!", "Name another player who played at the same club as the last one and extend the chain. A wrong answer costs a life; run out and you lose!", "Escribe otro jugador que haya jugado en el mismo club que el último y alarga la cadena. Un error cuesta una vida; ¡quien se quede sin vidas pierde!", "Escreva outro jogador que atuou no mesmo clube do último e aumente a corrente. Um erro custa uma vida; quem ficar sem vidas perde!", "Nenne einen Spieler, der beim selben Verein wie der letzte gespielt hat, und verlängere die Kette. Ein Fehler kostet ein Leben – ohne Leben verlierst du!", "Nomme un joueur passé par le même club que le dernier et allonge la chaîne. Une erreur coûte une vie ; sans vie, tu perds !", "Scrivi un altro giocatore che ha giocato nello stesso club dell'ultimo e allunga la catena. Un errore costa una vita; chi le finisce perde!", "اكتب لاعبًا آخر لعب في نفس نادي اللاعب الأخير وأطل السلسلة. الإجابة الخاطئة تكلفك حياة، ومن تنفد حياته يخسر!"],
  "mode.chain.l1": ["Yıldız başlangıç · 4 can", "Star start · 4 lives", "Inicio estrella · 4 vidas", "Início com estrela · 4 vidas", "Star-Start · 4 Leben", "Départ star · 4 vies", "Inizio da stella · 4 vite", "بداية بنجم · 4 أرواح"],
  "mode.chain.l2": ["Tanınmış başlangıç", "Well-known start", "Inicio conocido", "Início conhecido", "Bekannter Start", "Départ connu", "Inizio noto", "بداية معروفة"],
